-- Azure SQL migration 0001: one table per entity of the first release.
-- Generated by SqlServerSchemaScript.GenerateTables from the logical model compiled into the engine core (model 0.1.0).
-- Do not edit by hand: run the local server's schema-script command, or the store tests with PRODUCT_WRITE_SQL=1.
--
-- Every table holds the engine's rows in the shape of its storage ports: the row ID, the configuration key path (null
-- for operational rows), the row's columns as canonical JSON in logical names, and an optimistic version. Beside them
-- are the performer of the last write and the promoted columns that the unique keys, the version probe and the
-- row-level security block predicates read, copied from the JSON by the store in the same statement.
-- History (document 22, sections 2.3 and 11.2): 61 system-versioned temporal tables, 4 updatable ledger tables
-- (C46, O08, O09, O10) and 4 append-only ledger tables (C02, O14, O20, O24).
-- Every statement checks before it acts, so the script can run again after a stop part way.

IF SCHEMA_ID(N'config') IS NULL EXEC (N'CREATE SCHEMA [config]');
IF SCHEMA_ID(N'ops') IS NULL EXEC (N'CREATE SCHEMA [ops]');
IF SCHEMA_ID(N'audit') IS NULL EXEC (N'CREATE SCHEMA [audit]');
IF SCHEMA_ID(N'security') IS NULL EXEC (N'CREATE SCHEMA [security]');
IF SCHEMA_ID(N'host') IS NULL EXEC (N'CREATE SCHEMA [host]');
GO

-- C01 Configuration Set (configuration-set): history class V, system-versioned temporal table. Delete policy: retire.
IF OBJECT_ID(N'[config].[ConfigurationSet]', N'U') IS NULL
BEGIN
    CREATE TABLE [config].[ConfigurationSet]
    (
        [Id] varchar(36) COLLATE Latin1_General_BIN2 NOT NULL,
        [Key] nvarchar(450) COLLATE Latin1_General_BIN2 NULL,
        [Columns] nvarchar(max) NOT NULL,
        [Version] bigint NOT NULL,
        [PerformedByPrincipalId] nvarchar(64) COLLATE Latin1_General_BIN2 NULL,
        [PerformedByActorKind] nvarchar(32) COLLATE Latin1_General_BIN2 NULL,
        [IsInForce] bit NULL,
        [CurrentVersionNumber] int NULL,
        [CreatedOn] datetime2(3) NOT NULL CONSTRAINT [DF_ConfigurationSet_CreatedOn] DEFAULT (SYSUTCDATETIME()),
        [ModifiedOn] datetime2(3) NOT NULL CONSTRAINT [DF_ConfigurationSet_ModifiedOn] DEFAULT (SYSUTCDATETIME()),
        [ValidFrom] datetime2(7) GENERATED ALWAYS AS ROW START HIDDEN NOT NULL,
        [ValidTo] datetime2(7) GENERATED ALWAYS AS ROW END HIDDEN NOT NULL,
        PERIOD FOR SYSTEM_TIME ([ValidFrom], [ValidTo]),
        CONSTRAINT [PK_ConfigurationSet] PRIMARY KEY CLUSTERED ([Id]),
        CONSTRAINT [CK_ConfigurationSet_Columns] CHECK (ISJSON([Columns]) = 1)
    )
    WITH (SYSTEM_VERSIONING = ON (HISTORY_TABLE = [config].[ConfigurationSetHistory]));
END;
GO

